/* kn_gs.c — NVST RTP/GS parse layer (contract: kn_gs.h).
 *
 * Line-by-line port of nvst.rs @ a49b124; every function carries its
 * provenance range. The known-answer vectors (kn_gs_kat_vectors.h,
 * generated by the independent tools/gs_reference.py) pin the behaviour —
 * if this file disagrees with a vector, THIS FILE is wrong.
 *
 * Pure, zero-allocation, no globals. Endianness is explicit (pitfall #1:
 * RTP big-endian, GS body little-endian).
 */
#include "kn/kn_gs.h"

#include <string.h>

/* ------------------------------------------------------------ endian helpers */

static uint32_t gs_be32(const uint8_t *p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}
static uint32_t gs_le32(const uint8_t *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

/* ------------------------------------------------------ RTP header+payload */

/* nvst.rs:2456-2510 (parse) + 2512-2525 (payload, padding strip). */
int kn_gs_rtp_parse(const uint8_t *pkt, size_t len, kn_gs_rtp *out)
{
    unsigned first, cc, profile, words;
    size_t payload_off, end;

    if (!pkt || !out) return KN_GS_ERR_ARGS;
    memset(out, 0, sizeof *out);

    if (len < KN_GS_FIXED_HEADER_LEN) return KN_GS_ERR_TOO_SHORT;
    first = pkt[0];
    if ((first >> 6) != 2u) return KN_GS_ERR_VERSION;
    cc = first & 0x0Fu;
    payload_off = KN_GS_FIXED_HEADER_LEN + (size_t)cc * 4u;
    if (len < payload_off) return KN_GS_ERR_CSRC;

    if (first & 0x10u) {
        size_t ext_end;
        if (len < payload_off + 4u) return KN_GS_ERR_EXT;
        profile = ((unsigned)pkt[payload_off] << 8) |
                  (unsigned)pkt[payload_off + 1];
        words = ((unsigned)pkt[payload_off + 2] << 8) |
                (unsigned)pkt[payload_off + 3];
        ext_end = payload_off + (size_t)words * 4u + 4u;
        if (len < ext_end) return KN_GS_ERR_EXT;
        if (profile == KN_GS_PROFILE) {
            /* STRICT: the GS extension must be exactly 16 bytes
             * (nvst.rs:2490; test gs_extension_requires_exactly_four_words
             * at nvst.rs:12099). */
            if ((size_t)words * 4u != KN_GS_EXT_LEN) return KN_GS_ERR_EXT;
            out->gs_off = (unsigned)(payload_off + 4u);
            out->has_gs = 1;
        }
        /* foreign extension profiles are skipped, not rejected — the
         * missing-video verdict belongs to the consumer (MissingNvVideoHeader
         * is raised by the assembler, nvst.rs:3231). */
        payload_off = ext_end;
    }

    out->pt = pkt[1] & 0x7Fu;
    out->seq = ((unsigned)pkt[2] << 8) | (unsigned)pkt[3];
    out->timestamp = gs_be32(pkt + 4);
    out->ssrc = gs_be32(pkt + 8);
    out->has_padding = (first & 0x20u) ? 1 : 0;

    end = len;
    if (out->has_padding) {
        unsigned padding = pkt[len - 1];
        if (padding == 0u || (size_t)padding > end - payload_off)
            return KN_GS_ERR_PADDING;
        end -= padding;
    }
    out->payload_off = (unsigned)payload_off;
    out->payload_len = (unsigned)(end - payload_off);
    return KN_GS_OK;
}

/* ------------------------------------------------------------- GS 16B body */

/* nvst.rs:3228-3257 (NvVideoPacket::parse + frame-boundary predicates).
 * flags_valid mirrors the recovered-packet validation at nvst.rs:4089. */
int kn_gs_video_parse(const uint8_t ext16[KN_GS_EXT_LEN], kn_gs_video *out)
{
    uint32_t packet_word, flags_word, fec_word;
    unsigned ext11;

    if (!ext16 || !out) return KN_GS_ERR_ARGS;
    memset(out, 0, sizeof *out);

    packet_word = gs_le32(ext16 + 0);
    flags_word  = gs_le32(ext16 + 8);
    fec_word    = gs_le32(ext16 + 12);
    ext11       = ext16[11];                  /* pitfall #2 */

    out->stream_packet_index = (packet_word >> 8) & KN_GS_INDEX_MASK;
    out->frame_index         = gs_le32(ext16 + 4);
    out->flags               = flags_word & 0x0Fu;
    out->fec_current_block   = (ext11 >> 4) & 0x03u;
    out->fec_last_block      = (ext11 >> 6) & 0x03u;
    out->fec_percentage      = (fec_word >> 4) & 0xFFu;
    out->fec_index           = (fec_word >> 12) & 0x3FFu;
    out->fec_source_packets  = (fec_word >> 22) & 0x3FFu;
    out->is_fec = (out->fec_percentage != 0u &&
                   out->fec_index >= out->fec_source_packets) ? 1 : 0;
    out->is_start_of_frame = ((out->flags & KN_GS_FLAG_SOF) &&
                              out->fec_current_block == 0u) ? 1 : 0;
    out->is_end_of_frame = ((out->flags & KN_GS_FLAG_EOF) &&
                            out->fec_current_block == out->fec_last_block)
                           ? 1 : 0;
    out->flags_valid =
        (out->flags & ~(unsigned)(KN_GS_FLAG_SOF | KN_GS_FLAG_EOF |
                                  KN_GS_FLAG_PIC)) == 0u ? 1 : 0;
    return KN_GS_OK;
}

/* ------------------------------------------------------------ Annex-B scan */

/* nvst.rs:3525-3534 — bytes.windows(3): offsets 0..len-3; at each offset
 * the 3-byte pattern is tested first, the 4-byte variant additionally
 * requires b[off+3] == 1 INSIDE the searched slice. */
int kn_gs_find_start_code(const uint8_t *b, size_t len,
                          size_t *off, size_t *prefix_len)
{
    size_t o;
    if (!b || !off || !prefix_len) return KN_GS_ERR_ARGS;
    if (len < 3u) return KN_GS_ERR_NO_PICTURE;
    for (o = 0; o + 3u <= len; ++o) {
        if (b[o] == 0u && b[o + 1] == 0u && b[o + 2] == 1u) {
            *off = o;
            *prefix_len = 3u;
            return KN_GS_OK;
        }
        if (b[o] == 0u && b[o + 1] == 0u && b[o + 2] == 0u &&
            o + 3u < len && b[o + 3] == 1u) {
            *off = o;
            *prefix_len = 4u;
            return KN_GS_OK;
        }
    }
    return KN_GS_ERR_NO_PICTURE;
}

/* nvst.rs:3481-3497 (video_picture_payload). */
int kn_gs_picture_payload(int codec, const uint8_t *pay, size_t len,
                          size_t *off)
{
    if (!pay || !off) return KN_GS_ERR_ARGS;
    if (codec == KN_GS_CODEC_H264 || codec == KN_GS_CODEC_H265) {
        size_t search = len < (size_t)KN_GS_START_SEARCH
                      ? len : (size_t)KN_GS_START_SEARCH;
        size_t pl;
        int rc = kn_gs_find_start_code(pay, search, off, &pl);
        return rc == KN_GS_OK ? KN_GS_OK : KN_GS_ERR_NO_PICTURE;
    }
    if (codec == KN_GS_CODEC_AV1) {
        /* AV1 has no start code — fixed GFN cloud header sizes (NOT the
         * similarly named consumer-GameStream layout; nvst.rs:3489-3492). */
        if (len == 0u) return KN_GS_ERR_NO_PICTURE;
        if (pay[0] == 0x01u) {
            if (len < KN_GS_AV1_SHORT_HEADER) return KN_GS_ERR_NO_PICTURE;
            *off = KN_GS_AV1_SHORT_HEADER;
            return KN_GS_OK;
        }
        if (pay[0] == 0x81u) {
            if (len < KN_GS_AV1_GFN_HEADER) return KN_GS_ERR_NO_PICTURE;
            *off = KN_GS_AV1_GFN_HEADER;
            return KN_GS_OK;
        }
        return KN_GS_ERR_NO_PICTURE;
    }
    return KN_GS_ERR_ARGS;
}

/* nvst.rs:3500-3523 (video_access_unit_is_keyframe). */
int kn_gs_is_keyframe(int codec, const uint8_t *b, size_t len,
                      int frame_header_hint)
{
    size_t off = 0;
    if (codec == KN_GS_CODEC_AV1) return frame_header_hint ? 1 : 0;
    if (!b) return 0;
    for (;;) {
        size_t so, pl, nal_start;
        if (kn_gs_find_start_code(b + off, len - off, &so, &pl) != KN_GS_OK)
            return 0;
        nal_start = off + so + pl;
        if (nal_start < len) {
            unsigned h = b[nal_start];
            if (codec == KN_GS_CODEC_H264 && (h & 0x1Fu) == 5u) return 1;
            if (codec == KN_GS_CODEC_H265) {
                unsigned t = (h >> 1) & 0x3Fu;
                if (t >= 16u && t <= 21u) return 1;
            }
        }
        off = nal_start;      /* always advances (pl >= 3) */
    }
}

/* nvst.rs:3458-3479 (strip_trailing_access_unit_delimiter). */
size_t kn_gs_strip_trailing_aud(int codec, const uint8_t *b, size_t len)
{
    size_t off = 0, last_start = 0, last_nal = 0;
    int have_last = 0;
    if (codec == KN_GS_CODEC_AV1) return len;
    if (!b) return len;
    for (;;) {
        size_t so, pl;
        if (kn_gs_find_start_code(b + off, len - off, &so, &pl) != KN_GS_OK)
            break;
        last_start = off + so;
        last_nal = last_start + pl;
        have_last = 1;
        off = last_nal;
    }
    if (have_last && last_nal < len) {
        unsigned h = b[last_nal];
        if (codec == KN_GS_CODEC_H264 && (h & 0x1Fu) == 9u) return last_start;
        if (codec == KN_GS_CODEC_H265 && ((h >> 1) & 0x3Fu) == 35u)
            return last_start;
    }
    return len;
}

/* ------------------------------------------------------------- FEC layout */

/* nvst.rs:3677-3701 (FecPacketLayout::from_packet). */
int kn_gs_fec_layout_parse(const uint8_t ext16[KN_GS_EXT_LEN], kn_gs_fec_layout *out)
{
    uint32_t fec_word;
    unsigned pct, shard, data, parity, total;

    if (!ext16 || !out) return KN_GS_ERR_ARGS;
    memset(out, 0, sizeof *out);
    out->frame_index = gs_le32(ext16 + 4);
    fec_word = gs_le32(ext16 + 12);
    pct   = (fec_word >> 4) & 0xFFu;
    shard = (fec_word >> 12) & 0x3FFu;
    data  = (fec_word >> 22) & 0x3FFu;
    if (data == 0u || pct == 0u) return KN_GS_ERR_FEC_LAYOUT;
    parity = (data * pct + 99u) / 100u;    /* div_ceil; product <= 260 865 */
    total = data + parity;
    if (parity == 0u || shard >= total || total > 1023u)
        return KN_GS_ERR_FEC_LAYOUT;
    out->block_index      = (ext16[11] >> 4) & 0x03u;
    out->last_block_index = (ext16[11] >> 6) & 0x03u;
    out->shard_index      = shard;
    out->data_shards      = data;
    out->parity_shards    = parity;
    return KN_GS_OK;
}

/* nvst.rs:4813-4824 (same-frame stream_packet_index continuity). */
int kn_gs_index_continuous(uint32_t last, uint32_t idx)
{
    return ((last + 1u) & KN_GS_INDEX_MASK) == idx ? 1 : 0;
}

/* ----------------------------------------------------------- AU assembly */

static int gs_au_frame_type_valid(unsigned wire)
{
    return wire >= KN_GS_FRAME_P && wire <= KN_GS_FRAME_NON_REF_P;
}

static void gs_au_reset_frame(kn_gs_au_assembler *assembler)
{
    assembler->bytes_len = 0;
    assembler->current_frame = 0;
    assembler->first_stream_packet_index = 0;
    assembler->last_stream_packet_index = 0;
    assembler->expected_access_unit_length = 0;
    assembler->frame_type_wire = KN_GS_FRAME_UNKNOWN;
    assembler->last_packet_payload_length = 0;
    assembler->active = 0;
    assembler->frame_type_valid = 0;
    assembler->has_expected_access_unit_length = 0;
    assembler->has_last_packet_payload_length = 0;
}

int kn_gs_au_assembler_init(kn_gs_au_assembler *assembler, int codec,
                            uint8_t *buffer, size_t buffer_capacity,
                            size_t max_access_unit)
{
    if (!assembler || !buffer ||
        (codec != KN_GS_CODEC_H264 && codec != KN_GS_CODEC_H265 &&
         codec != KN_GS_CODEC_AV1))
        return KN_GS_ERR_ARGS;
    if (max_access_unit == 0) max_access_unit = KN_GS_DEFAULT_MAX_ACCESS_UNIT;
    if (max_access_unit > KN_GS_MAX_ACCESS_UNIT ||
        buffer_capacity < max_access_unit)
        return KN_GS_ERR_AU_STATE;

    memset(assembler, 0, sizeof *assembler);
    assembler->codec = codec;
    assembler->buffer = buffer;
    assembler->buffer_capacity = buffer_capacity;
    assembler->max_access_unit = max_access_unit;
    return 0;
}

void kn_gs_au_assembler_reset(kn_gs_au_assembler *assembler)
{
    if (assembler) gs_au_reset_frame(assembler);
}

static void gs_au_parse_frame_header(kn_gs_au_assembler *assembler,
                                     const uint8_t *payload, size_t len,
                                     size_t header_size)
{
    unsigned wire;
    if (assembler->codec == KN_GS_CODEC_AV1) {
        if (len < 4u || header_size == 0u ||
            (payload[0] != 0x01u && payload[0] != 0x81u))
            return;
        wire = payload[3];
    } else {
        if (len < 4u || header_size < 4u ||
            payload[0] != 0x47u || payload[1] != 0x53u)
            return;
        wire = payload[3] & 0x0Fu;
    }
    assembler->frame_type_wire = wire;
    assembler->frame_type_valid = gs_au_frame_type_valid(wire);
}

int kn_gs_au_assembler_push(kn_gs_au_assembler *assembler,
                            const kn_gs_video *video, uint32_t timestamp,
                            const uint8_t *payload, size_t payload_len,
                            kn_gs_access_unit *out)
{
    size_t picture_offset = 0, frame_header_size = 0, picture_len;
    const uint8_t *picture = payload;
    int rc, is_start, is_end;

    if (!assembler || !assembler->buffer || !video || !out ||
        (!payload && payload_len) || assembler->max_access_unit == 0 ||
        assembler->max_access_unit > assembler->buffer_capacity)
        return KN_GS_ERR_ARGS;
    memset(out, 0, sizeof *out);
    out->codec = assembler->codec;
    if (video->is_fec) return KN_GS_ERR_AU_FEC;

    is_start = video->is_start_of_frame != 0;
    is_end = video->is_end_of_frame != 0;
    if (is_start) {
        if (assembler->active && assembler->bytes_len > 0) {
            out->discarded_incomplete_frame = 1;
            out->request_keyframe = 1;
        }
        gs_au_reset_frame(assembler);
        rc = kn_gs_picture_payload(assembler->codec, payload, payload_len,
                                   &picture_offset);
        if (rc != KN_GS_OK) {
            out->request_keyframe = 1;
            return rc;
        }
        frame_header_size = picture_offset;
        picture = payload + picture_offset;
        assembler->active = 1;
        assembler->current_frame = video->frame_index;
        assembler->first_stream_packet_index = video->stream_packet_index;
        assembler->last_stream_packet_index = video->stream_packet_index;
        gs_au_parse_frame_header(assembler, payload, payload_len,
                                 frame_header_size);
        if (assembler->codec == KN_GS_CODEC_AV1 && payload_len >= 6u &&
            payload[0] == 0x01u) {
            assembler->last_packet_payload_length =
                (uint16_t)((unsigned)payload[4] |
                           ((unsigned)payload[5] << 8));
            assembler->has_last_packet_payload_length = 1;
        } else if (assembler->codec == KN_GS_CODEC_AV1 &&
                   payload_len >= KN_GS_AV1_GFN_HEADER &&
                   payload[0] == 0x81u) {
            assembler->expected_access_unit_length =
                gs_le32(payload + 16);
            assembler->has_expected_access_unit_length = 1;
        }
        if (assembler->has_expected_access_unit_length &&
            assembler->expected_access_unit_length >
                assembler->max_access_unit) {
            gs_au_reset_frame(assembler);
            out->request_keyframe = 1;
            return KN_GS_ERR_AU_TOO_LARGE;
        }
    } else {
        if (!assembler->active ||
            assembler->current_frame != video->frame_index) {
            gs_au_reset_frame(assembler);
            out->request_keyframe = 1;
            return KN_GS_ERR_AU_AWAITING_SOF;
        }
        if (!kn_gs_index_continuous(assembler->last_stream_packet_index,
                                    video->stream_packet_index)) {
            gs_au_reset_frame(assembler);
            out->request_keyframe = 1;
            return KN_GS_ERR_AU_DISCONTINUITY;
        }
        assembler->last_stream_packet_index = video->stream_packet_index;
    }

    picture_len = payload_len - picture_offset;
    if (assembler->codec == KN_GS_CODEC_AV1 && is_end &&
        assembler->has_last_packet_payload_length) {
        size_t reported = assembler->last_packet_payload_length;
        if (reported >= frame_header_size) {
            size_t exact_len = reported - frame_header_size;
            if (exact_len > 0 && exact_len <= picture_len) {
                picture_len = exact_len;
            } else {
                out->length_hint_ignored = 1;
            }
        } else {
            out->length_hint_ignored = 1;
        }
    }

    if (picture_len > assembler->max_access_unit - assembler->bytes_len) {
        gs_au_reset_frame(assembler);
        out->request_keyframe = 1;
        return KN_GS_ERR_AU_TOO_LARGE;
    }
    if (picture_len) {
        memcpy(assembler->buffer + assembler->bytes_len, picture, picture_len);
        assembler->bytes_len += picture_len;
    }
    out->timestamp = timestamp;
    if (!is_end) return KN_GS_AU_NEED_MORE;

    if (assembler->has_expected_access_unit_length) {
        size_t expected = assembler->expected_access_unit_length;
        if (expected == 0u || expected > assembler->bytes_len) {
            gs_au_reset_frame(assembler);
            out->request_keyframe = 1;
            return KN_GS_ERR_AU_LENGTH;
        }
        assembler->bytes_len = expected;
    }
    assembler->bytes_len = kn_gs_strip_trailing_aud(assembler->codec,
                                                     assembler->buffer,
                                                     assembler->bytes_len);

    out->frame_index = video->frame_index;
    out->first_stream_packet_index = assembler->first_stream_packet_index;
    out->frame_type_wire = assembler->frame_type_wire;
    out->frame_type_valid = assembler->frame_type_valid;
    out->keyframe = kn_gs_is_keyframe(assembler->codec, assembler->buffer,
            assembler->bytes_len,
            assembler->codec == KN_GS_CODEC_AV1 && assembler->frame_type_valid &&
            assembler->frame_type_wire == KN_GS_FRAME_I);
    out->contiguous = !out->discarded_incomplete_frame;
    out->bytes = assembler->buffer;
    out->bytes_len = assembler->bytes_len;
    gs_au_reset_frame(assembler);
    return KN_GS_AU_COMPLETE;
}

/* ------------------------------------------------------ kn_ring_dump lines */

/* Field tokenizer: fields are separated by EXACTLY one space (the writer is
 * knring.c dump_visit's fprintf); \r\n tolerated at end of line. Returns 1
 * when another field follows, 0 at end of line. */
static int gs_hd_field(const char **pp, const char **fs, const char **fe)
{
    const char *s = *pp;
    const char *e = s;
    while (*e != '\0' && *e != ' ' && *e != '\r' && *e != '\n') ++e;
    *fs = s;
    *fe = e;
    if (*e == ' ') { *pp = e + 1; return 1; }
    *pp = e;                       /* at \r, \n or NUL */
    return 0;
}

static int gs_hd_u64(const char *s, const char *e, uint64_t *out)
{
    uint64_t v = 0;
    if (s == e) return -1;
    for (; s < e; ++s) {
        if (*s < '0' || *s > '9') return -1;
        if (v > (UINT64_MAX - 9u) / 10u) return -1;      /* overflow */
        v = v * 10u + (uint64_t)(*s - '0');
    }
    *out = v;
    return 0;
}

static int gs_hd_u32_dec(const char *s, const char *e, uint32_t *out)
{
    uint64_t v;
    if (gs_hd_u64(s, e, &v) != 0 || v > UINT32_MAX) return -1;
    *out = (uint32_t)v;
    return 0;
}

static int gs_hd_hexval(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int gs_hd_hex(const char *s, const char *e, uint32_t *out)
{
    uint32_t v = 0;
    if (s == e) return -1;
    for (; s < e; ++s) {
        int d = gs_hd_hexval(*s);
        if (d < 0) return -1;
        v = (v << 4) | (uint32_t)d;
    }
    *out = v;
    return 0;
}

int kn_gs_hexdump_parse_line(const char *line, kn_gs_dump_rec *rec,
                             uint8_t *payload, size_t cap, size_t *out_len)
{
    const char *p = line;
    const char *fs, *fe;
    uint32_t meta, flags, ln, i;
    int more;

    if (!line || !rec || !out_len) return KN_GS_ERR_ARGS;
    memset(rec, 0, sizeof *rec);
    *out_len = 0;

    /* <mono_us> <meta_hex> <flags> <len> */
    more = gs_hd_field(&p, &fs, &fe);
    if (!more || gs_hd_u64(fs, fe, &rec->mono_us) != 0) return KN_GS_ERR_HEX;
    more = gs_hd_field(&p, &fs, &fe);
    if (!more || (size_t)(fe - fs) != 8u || gs_hd_hex(fs, fe, &meta) != 0)
        return KN_GS_ERR_HEX;
    rec->meta = meta;
    more = gs_hd_field(&p, &fs, &fe);
    if (!more || gs_hd_u32_dec(fs, fe, &flags) != 0) return KN_GS_ERR_HEX;
    rec->flags = flags;
    more = gs_hd_field(&p, &fs, &fe);
    if (gs_hd_u32_dec(fs, fe, &ln) != 0) return KN_GS_ERR_HEX;
    rec->len = ln;

    /* exactly ln two-hex-digit byte tokens, then end-of-line. `more` from
     * the LAST consumed token must be 0 — that rejects extra tokens AND a
     * trailing space (python split(" ") sees an empty extra token there;
     * both verdicts must agree because the vectors are the contract).
     * Validation precedes the capacity verdict: a malformed line never
     * reports HEX_CAP. */
    for (i = 0; i < ln; ++i) {
        uint32_t byte;
        more = gs_hd_field(&p, &fs, &fe);
        if ((size_t)(fe - fs) != 2u || gs_hd_hex(fs, fe, &byte) != 0)
            return KN_GS_ERR_HEX;
        if (i + 1u < ln && !more) return KN_GS_ERR_HEX;  /* tokens ran out */
        if (payload && ln <= cap) payload[i] = (uint8_t)byte;
    }
    if (more) return KN_GS_ERR_HEX;

    if (ln > cap) {
        if (!payload) {                         /* fields-only mode */
            *out_len = ln;
            return KN_GS_OK;
        }
        return KN_GS_ERR_HEX_CAP;
    }
    *out_len = ln;
    return KN_GS_OK;
}
